function validate([grid]) {
  const n = grid.length;
  if (n < 1 || n > 500) return 'grid needs 1 to 500 rows.';
  const m = grid[0].length;
  if (m < 1 || m > 500) return 'grid needs 1 to 500 columns.';
  for (const row of grid) {
    if (row.length !== m) return 'Every row needs the same number of cells.';
    if (row.some(v => v !== 0 && v !== 1 && v !== 2)) return 'Each cell holds 0, 1 or 2.';
  }
  return null;
}

