function lenOfVDiagonal(grid) {
  const n = grid.length;
  const m = grid[0].length;
  const dirs = [[1, 1], [1, -1], [-1, -1], [-1, 1]];
  const memo = new Int32Array(n * m * 8);
  const holds = (row, col, value) => row >= 0 && row < n && col >= 0 && col < m && grid[row][col] === value;

  const extend = (row, col, dir, canTurn) => {
    const key = ((row * m + col) * 4 + dir) * 2 + canTurn;
    if (memo[key] > 0) {
      return memo[key];
    }
    const want = grid[row][col] === 2 ? 0 : 2;
    let best = 1;
    const [dr, dc] = dirs[dir];
    if (holds(row + dr, col + dc, want)) {
      best = 1 + extend(row + dr, col + dc, dir, canTurn);
    }
    if (canTurn === 1) {
      const turned = (dir + 1) % 4;
      const [tr, tc] = dirs[turned];
      if (holds(row + tr, col + tc, want)) {
        best = Math.max(best, 1 + extend(row + tr, col + tc, turned, 0));
      }
    }
    memo[key] = best;
    return best;
  };

  let answer = 0;
  for (let row = 0; row < n; row++) {
    for (let col = 0; col < m; col++) {
      if (grid[row][col] !== 1) {
        continue;
      }
      for (let dir = 0; dir < 4; dir++) {
        answer = Math.max(answer, extend(row, col, dir, 1));
      }
    }
  }
  return answer;
}

