function lenOfVDiagonal(grid) {
  // From every 1 and every first direction, walk the first leg cell by cell; at each of its cells, try
  // turning clockwise there and walk the second leg as far as the pattern allows.
  const n = grid.length, m = grid[0].length;
  const steps = [[1, 1], [1, -1], [-1, -1], [-1, 1]];
  const valueAt = (k) => (k === 0 ? 1 : k % 2 === 1 ? 2 : 0);
  const fits = (r, c, k) => r >= 0 && r < n && c >= 0 && c < m && grid[r][c] === valueAt(k);
  let best = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      if (grid[i][j] !== 1) continue;
      for (let d = 0; d < 4; d++) {
        const [a, b] = steps[d], [p, q] = steps[(d + 1) % 4];
        for (let r = i, c = j, k = 0; fits(r, c, k); r += a, c += b, k++) {
          let length = k + 1;
          for (let r2 = r + p, c2 = c + q; fits(r2, c2, length); r2 += p, c2 += q) length++;
          best = Math.max(best, length);
        }
      }
    }
  }
  return best;
}

