function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(70, 100) : int(1, 6);
  const m = large ? int(70, 100) : int(1, 6);
  // Mostly a pattern where 2 and 0 alternate from row to row (or column to column): every diagonal step
  // moves to the other kind, so long segments exist. Noise and scattered 1s break it up.
  const random = rand() < 0.25;
  const byRow = rand() < 0.5, shift = int(0, 1);
  const noise = large ? [0.002, 0.02, 0.1][int(0, 2)] : [0, 0.1, 0.3][int(0, 2)];
  const grid = Array.from({ length: n }, (_, r) => Array.from({ length: m }, (_, c) => {
    if (random || rand() < noise) return int(0, 2);
    return ((byRow ? r : c) + shift) % 2 === 0 ? 2 : 0;
  }));
  const ones = large ? int(1, 30) : int(0, 3);
  for (let k = 0; k < ones; k++) grid[int(0, n - 1)][int(0, m - 1)] = 1;
  return [grid];
}
